<VERSION_A>
   1 | BGD_DECLARE(void) gdImageFillToBorder (gdImagePtr im, int x, int y, int border, int color)
   2 | {
   3 | 	int lastBorder;
   4 | 	/* Seek left */
   5 | 	int leftLimit, rightLimit;
   6 | 	int i;
   7 | 	int restoreAlphaBleding;
   8 | 
   9 | 	if (border < 0) {
  10 | 		/* Refuse to fill to a non-solid border */
  11 | 		return;
  12 | 	}
  13 | 
  14 | 	leftLimit = (-1);
  15 | 
  16 | 	restoreAlphaBleding = im->alphaBlendingFlag;
  17 | 	im->alphaBlendingFlag = 0;
  18 | 
  19 | 	if (x >= im->sx) {
  20 | 		x = im->sx - 1;
  21 | 	} else if (x < 0) {
  22 | 		x = 0;
  23 | 	}
  24 | 	if (y >= im->sy) {
  25 | 		y = im->sy - 1;
  26 | 	} else if (y < 0) {
  27 | 		y = 0;
  28 | 	}
  29 | 	
  30 | 	for (i = x; (i >= 0); i--) {
  31 | 		if (gdImageGetPixel (im, i, y) == border) {
  32 | 			break;
  33 | 		}
  34 | 		gdImageSetPixel (im, i, y, color);
  35 | 		leftLimit = i;
  36 | 	}
  37 | 	if (leftLimit == (-1)) {
  38 | 		im->alphaBlendingFlag = restoreAlphaBleding;
  39 | 		return;
  40 | 	}
  41 | 	/* Seek right */
  42 | 	rightLimit = x;
  43 | 	for (i = (x + 1); (i < im->sx); i++) {
  44 | 		if (gdImageGetPixel (im, i, y) == border) {
  45 | 			break;
  46 | 		}
  47 | 		gdImageSetPixel (im, i, y, color);
  48 | 		rightLimit = i;
  49 | 	}
  50 | 	/* Look at lines above and below and start paints */
  51 | 	/* Above */
  52 | 	if (y > 0) {
  53 | 		lastBorder = 1;
  54 | 		for (i = leftLimit; (i <= rightLimit); i++) {
  55 | 			int c;
  56 | 			c = gdImageGetPixel (im, i, y - 1);
  57 | 			if (lastBorder) {
  58 | 				if ((c != border) && (c != color)) {
  59 | 					gdImageFillToBorder (im, i, y - 1, border, color);
  60 | 					lastBorder = 0;
  61 | 				}
  62 | 			} else if ((c == border) || (c == color)) {
  63 | 				lastBorder = 1;
  64 | 			}
  65 | 		}
  66 | 	}
  67 | 	/* Below */
  68 | 	if (y < ((im->sy) - 1)) {
  69 | 		lastBorder = 1;
  70 | 		for (i = leftLimit; (i <= rightLimit); i++) {
  71 | 			int c = gdImageGetPixel (im, i, y + 1);
  72 | 			if (lastBorder) {
  73 | 				if ((c != border) && (c != color)) {
  74 | 					gdImageFillToBorder (im, i, y + 1, border, color);
  75 | 					lastBorder = 0;
  76 | 				}
  77 | 			} else if ((c == border) || (c == color)) {
  78 | 				lastBorder = 1;
  79 | 			}
  80 | 		}
  81 | 	}
  82 | 	im->alphaBlendingFlag = restoreAlphaBleding;
  83 | }
</VERSION_A>

